package timeescape.ui;
import java.awt.*;import java.awt.event.*;import java.awt.image.BufferedImage;import java.nio.file.*;import javax.swing.*;import javax.imageio.ImageIO;import timeescape.core.GameState;
public class VerifyNotebook {
 static int checks;static void check(boolean b,String s){if(!b)throw new AssertionError(s);checks++;}
 static void layout(Container c){c.doLayout();for(Component x:c.getComponents())if(x instanceof Container n)layout(n);}
 static void render(GameHud h,int w,int height,String name)throws Exception{h.notebook.finishTurn();h.setSize(w,height);for(int i=0;i<4;i++)layout(h);BufferedImage im=new BufferedImage(w,height,BufferedImage.TYPE_INT_RGB);Graphics2D g=im.createGraphics();g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING,RenderingHints.VALUE_TEXT_ANTIALIAS_ON);h.printAll(g);g.dispose();ImageIO.write(im,"png",timeescape.testutil.ArtifactPaths.output("v54-release-tests/"+name+".png").toFile());}
 public static void main(String[] args)throws Exception{Files.createDirectories(timeescape.testutil.ArtifactPaths.output("v54-release-tests"));SwingUtilities.invokeAndWait(()->{try{
  GameFonts.installDefaults();GameState s=new GameState();String[] clicked={""};var scene=new GameScenePanel(id->clicked[0]=id);scene.setEra(s.era());var m=new MissionPanel();var inv=new InventoryPanel(id->clicked[0]=id);var h=new GameHud(scene,m,inv,()->{},()->{},()->{});h.setLocationTitle("현재 · 연구실");m.refresh(s);inv.refresh(s,false);
  render(h,1440,810,"01-default");check(!h.notebook.isVisible(),"initial notebook hidden");Rectangle bounds=scene.getBounds();h.noteButton.doClick();render(h,1440,810,"02-records");check(h.notebook.isVisible()&&h.recordTab.isSelected(),"note opens records");check(bounds.equals(scene.getBounds()),"background unchanged on popup");
  h.inventoryTab.doClick();render(h,1440,810,"03-empty-inventory");check(h.inventoryTab.isSelected(),"inventory tab");h.getActionMap().get("closeNotebook").actionPerformed(new ActionEvent(h,0,""));check(!h.notebook.isVisible(),"Esc closes");h.noteButton.doClick();check(h.inventoryTab.isSelected(),"last tab remembered");
  s.complete("PZ004");s.collect("USB");s.collect("CASE");s.collect("CELL");s.collect("MODULE");inv.refresh(s,false);m.refresh(s);render(h,1440,810,"04-owned-items");check(inv.getComponentCount()==4,"actual items only");((JButton)inv.getComponent(0)).doClick();check(clicked[0].equals("USB"),"USB action");
  for(int[] size:new int[][]{{1020,650},{1280,720},{1920,1080},{2560,1080}}){render(h,size[0],size[1],"inventory-"+size[0]+"x"+size[1]);check(h.notebook.getX()>=0&&h.notebook.getY()+h.notebook.getHeight()<=h.layers.getHeight(),"popup within viewport");check(inv.getWidth()>=280*h.notebook.uiScale(),"item text space");h.recordTab.doClick();render(h,size[0],size[1],"records-"+size[0]+"x"+size[1]);h.inventoryTab.doClick();}
  h.notebook.finishTurn();s.complete("PZ006");s.complete("PZ001");s.complete("PZ007");s.complete("PZ008");s.complete("PZ010");s.complete("PZ011");inv.refresh(s,false);check(s.canDepart(),"parallel mission gate");((JButton)inv.getComponent(0)).doClick();check(clicked[0].equals("DEVICE"),"device action retained");check(inv.getComponentCount()==2,"consumed materials removed");s.moveToPast();s.collectSparePart();inv.refresh(s,true);m.refresh(s);((JButton)inv.getComponent(1)).doClick();check(clicked[0].equals("SPARE"),"spare action retained");s.repairWatch();s.moveToFuture();s.collectCorePart();inv.refresh(s,false);((JButton)inv.getComponent(1)).doClick();check(clicked[0].equals("CORE"),"core action retained");
  // Same display transform is used by painting and hit detection after cover scaling.
  var rect=GameScenePanel.class.getDeclaredMethod("displayRect");rect.setAccessible(true);var hit=GameScenePanel.class.getDeclaredMethod("hitTest",Point.class);hit.setAccessible(true);
  scene.setEra(timeescape.model.Era.PRESENT);for(int[] size:new int[][]{{1020,595},{1440,755},{2560,1025}}){scene.setSize(size[0],size[1]);Rectangle r=(Rectangle)rect.invoke(scene);check(r.width>=size[0]&&r.height>=size[1],"background fills viewport");for(var zone:timeescape.scene.HotspotCatalog.of(timeescape.model.Era.PRESENT)){Rectangle b=zone.bounds();Point p=new Point(r.x+(int)(b.getCenterX()*r.width/1920),r.y+(int)(b.getCenterY()*r.height/1080));if(scene.contains(p)&&zone.contains((int)b.getCenterX(),(int)b.getCenterY()))check(hit.invoke(scene,p)!=null,"visible hotspot maps");}}
  System.out.println("PASS "+checks+" notebook/layout/state/hit-map checks. No game main, JFrame or EXE launched.");
 }catch(Exception e){throw new RuntimeException(e);}});}
}

